.cn-manager {
	--grid-font: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji";
	z-index: 1099;
	width: 80vw;
	height: 75vh;
	min-height: 30em;
	display: flex;
	flex-direction: column;
	gap: 10px;
	color: var(--fg-color);
	font-family: arial, sans-serif;
	text-underline-offset: 3px;
	outline: none;
	margin: calc(var(--spacing)*2);
}

.cn-manager .cn-flex-auto {
	flex: auto;
}

.cn-manager button {
	width: auto;
	position: relative;
	overflow: hidden;
	font-size: 16px;
	color: var(--input-text);
	background-color: var(--comfy-input-bg);
	border-color: var(--border-color);
	margin: 0;
	min-width: 100px;
}

.cn-manager button:hover {
	filter: brightness(125%);
}

.cn-manager button:disabled,
.cn-manager input:disabled,
.cn-manager select:disabled {
	color: gray;
}

.cn-manager button:disabled {
	background-color: var(--comfy-input-bg);
}

.cn-manager .cn-manager-restart {
	display: none;
	background-color: #500000 !important;
	border-color: #88181b !important;
	color: white !important;
}

.cn-manager .cn-manager-restart:hover {
	background-color: #88181b !important;
}

.cn-manager .cn-manager-stop {
	display: none;
	background-color: #500000;
	color: white;
}

.cn-manager .cn-manager-back {
	align-items: center;
	justify-content: center;
}

.arrow-icon {
	height: 1em;
	width: 1em;
	margin-right: 5px;
	transform: translateY(2px);
}

.cn-icon {
	display: block;
	width: 16px;
	height: 16px;
}

